def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    aggressive = 0
    desperate_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 1.5:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= DAILY_SALARY * 0.9:
                aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    critical = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if critical:
        bid = max(DAILY_SALARY * 0.92, highest_prev + 2.0)
        if supply >= 22:
            bid += 4.0
        return float(max(0.0, min(budget, bid)))

    if supply <= 17:
        if aggressive >= 2 or highest_prev >= DAILY_SALARY * 1.4:
            bid = DAILY_SALARY * 0.18
        elif pressured:
            bid = max(DAILY_SALARY * 0.58, avg_prev * 0.72)
        else:
            bid = DAILY_SALARY * 0.26
        return float(max(0.0, min(budget, bid)))

    if supply >= 22:
        if desperate_opp >= 1:
            bid = max(DAILY_SALARY * 0.62, avg_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.52, avg_prev * 0.9)
        if pressured:
            bid = max(bid, DAILY_SALARY * 0.68)
        return float(max(0.0, min(budget, bid)))

    bid = DAILY_SALARY * (0.38 + 0.18 * (1.0 - scarcity))
    if highest_prev > 0:
        if highest_prev <= DAILY_SALARY * 0.75:
            bid = max(bid, highest_prev + 1.2)
        elif highest_prev <= DAILY_SALARY * 1.05:
            bid = max(bid, highest_prev * 0.92)
        else:
            bid = min(bid, DAILY_SALARY * 0.42)

    if pressured:
        bid = max(bid, DAILY_SALARY * 0.64)
    if rich_opp >= 2 and not pressured:
        bid = min(bid, DAILY_SALARY * 0.4)
    if day >= 8 and budget > DAILY_SALARY * 2:
        bid = max(bid, DAILY_SALARY * 0.6)

    return float(max(0.0, min(budget, bid)))

