def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o is None:
            continue
        if o.get('alive', False):
            alive_opps.append(o)

    if my_budget <= 0:
        return 0.0

    # If we are in danger, bid aggressively.
    if my_hp <= 2 or my_no_water_days >= 2:
        return min(my_budget, DAILY_SALARY * 0.95)

    # Read yesterday bids from alive opponents.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base bid depends on supply pressure.
    # With supply 15..25 and WATER_REQ=8, there are typically 1..3 water units available.
    # Use a higher base when supply is low (scarcer).
    if supply <= (MIN_SUPPLY + 0.5):
        base = DAILY_SALARY * 0.55
    elif supply >= (MAX_SUPPLY - 0.5):
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.50

    # If yesterday's bids were very high, we must match to avoid being shut out.
    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))

        # Empirically from context: survivors bid around ~113 (0.81*DAILY_SALARY).
        # If highest is above threshold, raise our bid.
        if highest_prev >= DAILY_SALARY * 0.80:
            bid = max(base, DAILY_SALARY * 0.62)
        # If average is high, slightly increase.
        elif avg_prev >= DAILY_SALARY * 0.55:
            bid = max(base, DAILY_SALARY * 0.58)
        else:
            # Otherwise, stay near base but add a small premium to beat low bidders.
            bid = base + 5.0

        # Add a small day-dependent adjustment to avoid ties.
        bid += (float(day) % 3) * 1.5
    else:
        bid = base

    # Hard cap by budget.
    if bid > my_budget:
        bid = my_budget

    # Ensure non-negative.
    if bid < 0:
        bid = 0.0

    return float(bid)
